from jsonlite import NA, DataFrame, rbind_pages
bound = rbind_pages([DataFrame({"foo": [1, 2], "bar": [True, False]}), DataFrame({"foo": [3], "col": ["blue"]})])
def cell(value):
    if value is NA:
        return "NA"
    if value is True:
        return "TRUE"
    if value is False:
        return "FALSE"
    return str(value)
rows = zip(bound.columns["foo"], bound.columns["bar"], bound.columns["col"])
print("|".join(":".join(cell(item) for item in row) for row in rows))
